#!/usr/bin/env python3
"""Build the self-contained, offline Chinese survey and local paper catalogue."""
import csv
import hashlib
import html
import json
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
records = sorted([json.loads(p.read_text()) for p in (ROOT/'research').glob('P[0-9][0-9].json')],key=lambda p:p['id'])
assert records and all(r['status'].startswith('downloaded') for r in records)
N_PAPERS = len(records)
notes = json.loads((ROOT/'research/paper_notes.json').read_text())
assert set(notes) == {r['id'] for r in records}, 'every paper needs notes, and every note needs a paper'
by_id = {r['id']:r for r in records}
families = {'latent':'潜变量与模型式控制','jepa':'JEPA / 特征预测','asset':'资产与仿真环境','factory':'工业过程与协同','gaussian':'高斯与动态重建','physics':'物理与高斯结合','video':'生成式交互模型','structured':'几何与结构化模型','reconstruction':'几何重建','evaluation':'评测','cutting':'形变、切削与材料去除','sim2wm':'仿真到世界模型与虚拟调试','spatial':'三维／四维世界模型','segmentation':'场景单体化'}
# Two levels: six world-model routes (路线), each realized by one or more of eight implementation options A–H (方案).
# Letters follow ROUTE_ORDER so that options read in route order everywhere.
ROUTE_ORDER = ['asset','recon','gsphys','dyn3d','video','jepa','latent','process']
ROUTE_LETTER = {k:chr(ord('A')+i) for i,k in enumerate(ROUTE_ORDER)}
ROUTE_SHORT = {'asset':'可执行资产','recon':'场景重建','gsphys':'高斯＋物理','dyn3d':'三维动力学','video':'生成式视频','jepa':'JEPA／特征预测','latent':'潜变量控制','process':'设备与生产流程'}
WM_ROUTES = [
 ('sim','显式仿真路线','资产 manipulation／数字孪生',['asset']),
 ('spatial','空间智能路线','三维／四维',['recon','gsphys','dyn3d']),
 ('videogen','生成式视频路线','像素空间',['video']),
 ('jepa','JEPA 路线','特征空间预测',['jepa']),
 ('latentrl','潜变量控制路线','Dreamer／TD-MPC',['latent']),
 ('flow','结构化流程路线','设备事件与生产流',['process']),
]
assert sorted(k for *_,ks in WM_ROUTES for k in ks)==sorted(ROUTE_ORDER)
ROUTE_GROUP_OF = {k:gname for _,gname,_,ks in WM_ROUTES for k in ks}
def group_link(gid):
    name=next(g for i,g,_,_ in WM_ROUTES if i==gid)
    return f'<a href="#group-{gid}">{name}</a>'
def route_name(key):
    return f'{ROUTE_LETTER[key]} {ROUTE_SHORT[key]}'
def route_link(key):
    return f'<a href="#route-{key}">{route_name(key)}</a>'
def resolve_refs(text, section_numbers):
    """Resolve {{sec:id}}, {{L:key,...}} (option letters) and {{R:key}} (linked option name)."""
    text=re.sub(r'\{\{sec:(\w+)\}\}',lambda m:section_numbers[m[1]],text)
    text=re.sub(r'\{\{L:([\w,]+)\}\}',lambda m:'、'.join(sorted(ROUTE_LETTER[k] for k in m[1].split(','))),text)
    text=re.sub(r'\{\{R:(\w+)\}\}',lambda m:route_link(m[1]),text)
    return text

supplementary = {s['id']:s for s in json.loads((ROOT/'research/supplementary_sources.json').read_text())}
KIND_ZH = {'official documentation':'官方文档','vendor announcement':'厂商公告','product page':'产品页面','essay':'文章','journal review (metadata only)':'期刊综述（仅核对元数据）','company page':'公司页面','news report':'新闻报道','technical blog':'技术博客'}
def cite(text):
    text=re.sub(r'\[\[(P\d{2})\]\]',lambda m:f'<a class="cite" href="#ref-{m[1]}" title="{html.escape(by_id[m[1]]["title"],quote=True)}">[{m[1]}]</a>',text)
    return re.sub(r'\[\[(S\d+)\]\]',lambda m:f'<a class="cite" href="#src-{m[1]}" title="{html.escape(supplementary[m[1]]["title"],quote=True)}">[{m[1]}]</a>',text)

def table(headers,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'

sections=[]
def section(sid,kicker,title,body):
    kicker=re.sub(r'^\d+',f'{len(sections)+1:02d}',kicker)
    sections.append((sid,title,f'<section id="{sid}"><div class="section-label">{kicker}</div><h2>{title}</h2>{cite(body)}</section>'))

section('scope','01 / 阅读边界','这份报告回答什么',r'''
<p class="lead">研究对象是<strong>包含多机台、多机器人、物流、设备控制和生产过程的工厂级世界模型</strong>。世界模型指能根据当前状态和动作预测未来的模型。核心问题不是把机械臂数量增加，而是能否在同一状态与时间语义下，预测操作、设备自主运行和外部扰动对空间、设备、工艺与生产流的共同影响。报告先梳理世界模型的主要路线（视频生成、空间智能、JEPA 等），再讨论它们落到工厂时各需要补什么。</p>
<div class="callout"><strong>本版只做 survey 与实现拆解，不选择路线。</strong>下文的路线梳理、优缺点对照、实现步骤和实验设计用于明确各路线的条件与缺口；不作优先级排序，不给出“最优路线”或最终架构建议。</div>
<div class="cards three"><article><span class="number">{{N_PAPERS}}</span><h3>论文全文</h3><p>全部保存至相邻 <code>papers/</code>，提供原文链接、本地 PDF、版本与 SHA-256。</p></article><article><span class="number">6</span><h3>世界模型路线</h3><p>显式仿真、空间智能、生成式视频、JEPA、潜变量控制、结构化流程；落到 8 个实现方案 A–H，可以组合，不是六选一。</p></article><article><span class="number">2</span><h3>机床建模选择</h3><p>角色（主动、被动、生产资源、仅观测）与表示（资产或场景）相互独立；同一台机床的不同部件可分别选择。</p></article></div>
<h3>报告结构</h3>
<p>第 {{sec:definition}} 节定义工厂级状态与任务。第 {{sec:wmroutes}}–{{sec:sim2wm}} 节梳理世界模型路线：六条路线及其进展，分类维度与八个实现方案，以及资产（manipulation）路线搭好场景后怎样成为世界模型。第 {{sec:machine}}–{{sec:deformation}} 节是工厂特有的两个建模问题：机床如何建模；形变、切削与材料去除。第 {{sec:simulator}} 节展开仿真器实现，涵盖物理步进、控制器、材料加工和产线联仿。第 {{sec:evidence}}–{{sec:comparison}} 节是相关工作的证据边界、各方案的实现步骤，以及各路线的优缺点对照（含场景单体化与推理时延）。第 {{sec:implementation}}–{{sec:evaluation}} 节是不依赖路线选择的工程、数据与评测工作。第 {{sec:problems}}–{{sec:questions}} 节列出未解问题和选路线前需要补充的现场信息。第 {{sec:papers}}–{{sec:sources}} 节是文献库与来源。</p>
<h3>文献范围与证据口径</h3>
<p>检索日期：<strong>2026-11-09，2026-11-11 与 2026-11-12 补充（Asia/Shanghai）</strong>。覆盖 2006–2026 年代表性研究，重点纳入 2024–2026 年动作条件预测、可交互重建、世界模型各路线及工业相关工作。检索使用论文题名及 factory / industrial / articulated / Gaussian / JEPA / world model / video world model / spatial intelligence / digital twin / virtual commissioning / machine tending / scheduling 等关键词，追查作者项目页和官方论文；论文身份与版本以本地保存的 arXiv 元数据及 PDF 为准。补充标准来自官方文档。</p>
<p>这是<strong>面向项目定义的定向综述</strong>，不是按 PRISMA 完成的穷尽性系统综述。每篇均核对题名、摘要与全文可读性；对 V-JEPA 2/2.1、DINO-WM、URDFormer、DreMa、ManiGaussian++、ArtiTwinSplat、工业 JEPA、AWMP、FMAPPO、PointWorld，以及形变与切削相关的 DiSECt、GaussianFluent、加工耦合模型等重点核对方法、实验及局限。没有在本机复现实验，也未审计全部代码或商业产品能力。</p>
<div class="legend"><span class="badge fact">文献证据</span> 论文作者或官方文档已报告的内容；<span class="badge analysis">分析判断</span> 本报告对工厂迁移条件的推导；<span class="badge design">待验证设计</span> 实现步骤、数据契约和测试方案，尚非实验结论。</div>
<h3>阅读时保留的五个区分</h3>
<ol><li><strong>场景表示与动力学目标是两个维度。</strong>资产／点云／高斯主要回答“存什么”；物理求解／JEPA／视频生成主要回答“怎么演化”。</li><li><strong>4D 复现与动作反事实不同。</strong>重放 <code>scene(t)</code> 不自动支持 <code>future(state, action)</code>。[[P17]][[P18]]</li><li><strong>资产不等于机器人。</strong>机床可以整体作为一个资产，但其中只有部分部件由自主控制器驱动（主动），其余是被操作的接口或只被观测的外壳。</li><li><strong>可预测图像不代表可预测产出。</strong>机台温度、夹紧力、磨损、质量和订单状态可能在画面中不可辨识。</li><li><strong>相近工作覆盖局部能力。</strong>本次纳入的论文没有共同验证“全厂空间＋设备控制＋加工质量＋物流排产”的端到端闭环。该判断限定于此文献集合，并非声称不存在其他系统。</li></ol>
''')

section('definition','02 / 问题形式化','从机械臂世界，扩展到工厂世界',r'''
<p><span class="badge analysis">分析判断</span> 单臂操作常把任务写成“看见物体—执行动作—达到目标”。工厂中还存在无人接触时自行加工的设备、在途工件、共享夹具、资源占用、工艺延迟、来料扰动与跨工序质量传播；“没有机器人动作”也不是“世界不变”。</p>
<div class="formula">sₜ = (Gₜ, Kₜ, Mₜ, Xₜ, Lₜ, Rₜ, Θₜ)<br>p(sₜ₊Δ, oₜ₊Δ, eₜ:ₜ₊Δ | bₜ, uₜ:ₜ₊Δ, ξₜ:ₜ₊Δ)<br>bₜ = p(sₜ | o₀:ₜ, u₀:ₜ₋₁)</div>
<p>这里的分解是<strong>需求分析用的状态清单</strong>，并不预设采用某种模型架构。<code>bₜ</code> 表示部分可观测情况下的状态信念；<code>ξ</code> 是到料、人员干预、故障等外生输入；<code>e</code> 为离散事件。需预测概率分布或不确定性，不能只给一条看似确定的未来。</p>
'''+table(['状态层','至少包含什么','仅靠普通视频容易漏掉什么'],[
['G · 几何／空间','厂房、通道、工位、对象姿态、碰撞域','遮挡内部、绝对尺度、薄结构与反光表面'],
['K · 运动／接触','机器人与机床轴、门、夹爪、工件速度、接触','摩擦、夹紧力、反冲、装夹公差'],
['M · 设备模式','自动／手动、程序段、门锁、报警、互锁','外观相同但许可和后续转移不同的设备状态'],
['X · 工艺与质量','温度、应力／应变、塑性／损伤历史、载荷、磨损、材料占用域和工件质量','材料去除、断裂新表面、切屑、内部缺陷与热漂移'],
['L · 生产流','工单、工序、批次、WIP、在途物流、交付时间','队列、批次血缘、返工和设备故障传播'],
['R · 资源与协同','机器人、机台、夹具、工具、共享区域占用','资源竞争、死锁、换型、搬运和等待'],
['Θ · 模型与参数','标定、物理／工艺参数、版本、置信度','维护后参数漂移及观测来源差异']
])+r'''
<h3>动作空间不止一个机械臂关节向量</h3>
<p><code>u = {机器人连续控制，机床轴／主轴／程序命令，按钮与门操作，任务派发／路由，工艺设定值}</code>。命令发出、控制器接受、执行开始、物理完成、观测到完成应分别记录；这几个时刻不能混成一个时间戳。若某机台的内部控制器被视为外部环境，也必须保留其模式与当前程序作为条件。</p>
<div class="figure"><svg viewBox="0 0 900 310" role="img" aria-label="工厂世界模型需要关联空间、设备、工艺、生产流四层状态">
<defs><marker id="arr" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0,0 L6,3 L0,6" fill="none" stroke="#62839b" stroke-width="1.4"/></marker></defs>
<g font-family="sans-serif" font-size="16"><rect x="15" y="25" width="195" height="115" rx="12" fill="#e6f3ef"/><text x="35" y="57" font-weight="700">空间与接触 · G/K</text><text x="35" y="88">对象 · 轨迹 · 遮挡</text><text x="35" y="116">碰撞 · 装夹 · 通行</text>
<rect x="240" y="25" width="195" height="115" rx="12" fill="#e7effa"/><text x="260" y="57" font-weight="700">设备执行 · M</text><text x="260" y="88">模式 · 命令 · 互锁</text><text x="260" y="116">自主循环 · 报警</text>
<rect x="465" y="25" width="195" height="115" rx="12" fill="#fff2dd"/><text x="485" y="57" font-weight="700">工艺与质量 · X</text><text x="485" y="88">材料 · 温度 · 磨损</text><text x="485" y="116">进度 · 公差 · 缺陷</text>
<rect x="690" y="25" width="195" height="115" rx="12" fill="#f0eafa"/><text x="710" y="57" font-weight="700">生产与物流 · L/R</text><text x="710" y="88">工单 · WIP · 资源</text><text x="710" y="116">交付 · 阻塞 · 排队</text>
<path d="M212 80H235 M437 80H460 M662 80H685" stroke="#62839b" stroke-width="2" marker-end="url(#arr)"/>
<path d="M112 144V186H788V144 M337 144V186 M563 144V186" fill="none" stroke="#9babb8" stroke-width="2"/>
<rect x="150" y="213" width="600" height="68" rx="12" fill="#102c3b"/><text x="450" y="240" text-anchor="middle" fill="white" font-weight="700">同一事件、身份与时间轴下的联合预测</text><text x="450" y="266" text-anchor="middle" fill="#d0e2eb" font-size="14">图中连线表示需求关联；不是选定的工程架构</text><path d="M450 186V207" stroke="#62839b" stroke-width="2" marker-end="url(#arr)"/></g></svg></div>
<h3>贯穿报告的示例任务</h3>
<p><span class="badge design">待验证设计</span> 使用一个假设的工厂片段解释接口：两台 CNC、两台移动操作机器人、上下料缓存、清洗／检测站、共享通道。任务为“毛坯配送—装夹—启动加工—等待—卸料—检测—流转或返工”。第 {{sec:machine}} 节的“按下启动”例子和第 {{sec:evaluation}} 节的对照试验都以这个片段为背景。该配置是分析示例，不假定用户已有这些硬件，也不代表最终规模。</p>
''')

section('wmroutes','03 / 世界模型路线','世界模型的六条路线：在什么空间里预测未来',(ROOT/'research/section_wm_routes.html').read_text())

section('taxonomy','04 / 分类框架','分类维度：表示、动态模型与八个实现方案',r'''
<p>第 {{sec:wmroutes}} 节的六条路线是按“在什么空间里预测”划分的。落到工程上，还要拆得更细，因为常被并列讨论的几个词其实不在同一层级。常说的“资产 manipulation 路线”，一般指用可执行资产（URDF／MJCF／USD）搭建场景，再在仿真里做操作。这里有两件事要分开：manipulation 是任务类型，资产是表示方式。USD 是场景描述与组合体系，不是动力学模型；URDF／MJCF 描述可执行结构的方式与 USD 不同，但无论哪种文件，本身都不足以构成设备的世界模型。OpenUSD 提供几何、材质和物理 schema，物理求解、控制程序与设备行为仍需由运行系统实现。<a href="https://openusd.org/release/index.html">[S1 · OpenUSD]</a></p>
<p>同理，资产、点云、高斯回答的是“存什么”，物理求解、JEPA、视频生成回答的是“怎么演化”，两类概念不在同一层级，不能直接拿来二选一。下表把常被并列讨论的概念拆到五个独立维度上。</p>
'''+table(['独立维度','可选项','不能直接推出的能力'],[
['实体／几何表示','CAD／mesh／URDF／MJCF／USD；点云／TSDF／SDF；3D／4DGS；latent tokens','有 mesh 不代表有控制；有高斯不代表没有对象；无 USD 不代表不能交互'],
['动态模型','解析物理；状态机／混合系统／离散事件；学得潜转移；三维点流／GNN；视频生成','渲染速度快不能推出物理 rollout 快；时序拟合不能推出动作因果'],
['训练目标','重建；掩码特征预测；动作条件多步预测；奖励／价值学习；逆物理参数辨识','特征预测并不必然是 JEPA；价值模型也不是完整物理模型'],
['决策与用途','状态估计／数字孪生；数据生成；MPC；策略学习；排程反事实','策略 π(a|o) 不自动是世界模型 p(s′|s,a)'],
['闭环程度','离线回放；开放环预测；仿真闭环；实机闭环；跨车间泛化','某个层级通过，不意味着更高层级也通过']
])+r'''
<h3>八个实现方案在这些维度上的位置</h3>
<p>六条路线落到工程上对应八个实现方案 A–H。每个方案是文献中常见的“表示＋动态模型＋训练方式”组合，<strong>可以组合，不是互斥的八选一</strong>。按上表的维度看，它们的位置如下：</p>
'''+table(['方案','所属路线','表示（存什么）','动态模型（怎么演化）','训练或构建方式','单独使用时的定位'],[
[route_link('asset'),ROUTE_GROUP_OF['asset'],'CAD／mesh／URDF／MJCF／USD 资产，含部件、关节、碰撞','解析物理求解＋设备逻辑','人工或自动建模，再用实测标定参数','本身可作为动作条件世界模型（仿真器）；设备行为与加工过程需另行写入'],
[route_link('recon'),ROUTE_GROUP_OF['recon'],'点云／TSDF／SDF／3D 与 4D 高斯','无；4D 只复现已观测到的时间变化','重建优化','世界模型的前端，不提供动作预测'],
[route_link('gsphys'),ROUTE_GROUP_OF['gsphys']+'（与显式仿真交叉）','高斯外观＋刚体／网格／粒子结构','物理求解（刚体、MPM、弹簧质点）','重建＋物理参数设定或逆向辨识','可做动作条件预测，限于已建模的物理过程'],
[route_link('dyn3d'),ROUTE_GROUP_OF['dyn3d'],'点／粒子／网格／对象图','学得的三维转移','动作条件点流，或以仿真器结果监督','可做几何层的动作条件预测；没有设备逻辑与工艺状态'],
[route_link('video'),ROUTE_GROUP_OF['video'],'像素或视频 token','生成模型','大规模视频预训练；动作条件来自后训练或潜动作','支持动作条件的模型可做预测；输出是画面，数值状态需另行读出'],
[route_link('jepa'),ROUTE_GROUP_OF['jepa'],'学得特征（视频或过程信号）','学得的动作条件特征转移','掩码特征预测预训练＋动作条件后训练','可做动作条件预测；输出是特征，需读出头才能对应可量测状态'],
[route_link('latent'),ROUTE_GROUP_OF['latent'],'学得潜状态','学得潜转移','潜状态推断＋奖励／价值学习','可做动作条件预测，但与特定任务和奖励绑定，重点在控制'],
[route_link('process'),ROUTE_GROUP_OF['process'],'实体、状态机、资源图','离散事件／混合系统转移','规则编码＋日志辨识','可做设备与生产事件层的预测；没有几何与接触']
])+r'''
<p>其中 {{L:recon}} 只提供表示，单独使用时是前端；{{L:latent}} 的重点是在学得的潜模型上做控制，潜模型与具体任务和奖励绑定。</p>
<p>已有工作也在跨方案组合：DreMa 与 Robo-GS 结合高斯外观和物理结构；PhysGaussian 直接把物理量附着到高斯；ArtiTwinSplat 可从高斯重建导出关节资产；DINO-WM 与 V-JEPA 2-AC 都在预训练特征空间里做规划。因此“资产或高斯只能选一个”不符合这些工作的实际做法。第 {{sec:comparison}} 节的对照表比较的是各路线原生覆盖什么、还要另加什么。[[P19]][[P22]][[P23]][[P27]][[P05]][[P07]]</p>
''')

