route_body='<p><span class="badge design">待验证设计</span> 六条世界模型路线（第 {{sec:wmroutes}} 节）落到工程上，对应八个实现方案 A–H。下面按路线分组，每个方案给出可实施的工作分解，回答“如果采用这个方案，需要补齐什么”。它们不是已完成的工程方案，排列顺序也不代表推荐顺序。每张卡片末尾统一列出四项：可交付物、主要未解问题、机床角色（对应第 {{sec:machine}} 节）、形变／切削需增加的工作（对应第 {{sec:deformation}} 节）。</p>'
route_by_key={r[0]:r for r in routes}
for gid,gname,gsub,keys in WM_ROUTES:
    route_body+=f'<h3 class="route-group" id="group-{gid}">{gname}<span>{gsub} · 方案 {"、".join(ROUTE_LETTER[k] for k in keys)}</span></h3>'
    for sid in keys:
        _,title,flow,description,refs,steps,output,bottleneck,machine=route_by_key[sid]
        letter=ROUTE_LETTER[sid]
        deform_add,deform_fail=deformation_by_route[sid]
        route_body+=f'<article class="route" id="route-{sid}"><div class="route-top"><span class="route-letter">{letter}</span><div><h4>{title}</h4><p>{flow}</p></div></div><p>{description} {refs}</p><ol class="steps">'+''.join(f'<li><strong>{title_}</strong><span>{text}</span></li>' for title_,text in steps)+'</ol>'+f'<div class="route-footer"><p><b>可交付物</b>　{output}</p><p><b>主要未解问题</b>　{bottleneck}</p><p><b>机床角色</b>　{machine}</p><p><b>形变／切削</b>　需增加：{deform_add}。验收必须能暴露：{deform_fail}。</p></div></article>'
section('routes','06 / 实现方案','八个实现方案，各自如何落地',route_body)

