JS=r'''
const search = document.querySelector('#paper-search');
const family = document.querySelector('#paper-family');
const papers = [...document.querySelectorAll('.paper')];
function filterPapers(){
  const q=search.value.trim().toLowerCase(), f=family.value;
  let n=0; papers.forEach(p=>{const show=(!q||p.dataset.search.includes(q))&&(f==='all'||p.dataset.family===f);p.hidden=!show;if(show)n++});
  document.querySelector('#paper-count').textContent=`${n} / ${papers.length}`;
  document.querySelector('#empty').hidden=n>0;
}
function resetFilters(){search.value='';family.value='all';filterPapers()}
search.addEventListener('input',filterPapers);family.addEventListener('change',filterPapers);
document.querySelector('#reset-filter').addEventListener('click',resetFilters);
document.querySelector('#print').addEventListener('click',()=>window.print());
function revealReference(){const id=decodeURIComponent(location.hash.slice(1));if(id.startsWith('ref-')){resetFilters();document.getElementById(id)?.scrollIntoView({behavior:'auto',block:'start'})}}
document.querySelectorAll('a.cite').forEach(a=>a.addEventListener('click',resetFilters));
window.addEventListener('hashchange',revealReference);revealReference();
const navLinks=[...document.querySelectorAll('nav a')];
const reportSections=[...document.querySelectorAll('main section')];
let navPending=false;
function updateNavigation(){let current=reportSections[0].id;for(const s of reportSections){if(s.getBoundingClientRect().top<=180)current=s.id;else break}navLinks.forEach(a=>a.classList.toggle('active',a.hash==='#'+current));navPending=false}
window.addEventListener('scroll',()=>{if(!navPending){navPending=true;requestAnimationFrame(updateNavigation)}},{passive:true});
window.addEventListener('resize',updateNavigation);updateNavigation();
'''

nav_labels={'scope':'范围与证据口径','definition':'工厂级状态与任务','wmroutes':'世界模型的六条路线','taxonomy':'分类维度与实现方案','sim2wm':'资产路线如何成为世界模型','machine':'机床角色与表示','deformation':'形变、切削与拓扑变化','simulator':'仿真器实现与联仿','evidence':'相关工作的验证边界','routes':'八个实现方案的步骤','comparison':'路线优缺点对照','implementation':'共通工程步骤','data':'数据与计算需求','evaluation':'统一评测与实验','problems':'当前问题与研究缺口','questions':'路线选择前的调查','papers':'{{N_PAPERS}} 篇论文与本地全文','sources':'来源与复核说明'}
assert set(nav_labels)=={sid for sid,_,_ in sections}, set(nav_labels)^{sid for sid,_,_ in sections}
nav_groups={'scope':'问题与范围','wmroutes':'世界模型路线','machine':'工厂特有问题','evidence':'证据、方案与对照','implementation':'共通工作','problems':'问题与下一步','papers':'附录'}
nav=''.join((f'<span class="nav-group">{nav_groups[sid]}</span>' if sid in nav_groups else '')+f'<a href="#{sid}">{i:02d}　{nav_labels[sid]}</a>' for i,(sid,title,_) in enumerate(sections,1))
body=''.join(s[2] for s in sections)
# Cross-references are written as {{sec:<id>}} and resolved to the final section number here.
section_numbers={sid:f'{i:02d}' for i,(sid,_,_) in enumerate(sections,1)}
body=resolve_refs(body,section_numbers)
assert not re.search(r'\{\{(sec|L|R):',body)
document=f'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="工厂级工业世界模型技术路线调研：资产、机床主动与被动建模、点云高斯、JEPA、视频生成、生产流程与三维动力学。"><title>工厂级工业世界模型 · 技术路线调研</title><style>{CSS}</style></head><body id="top"><aside class="sidebar"><div class="brand">INDUSTRIAL WORLD MODELS</div><h2>工厂级工业世界模型<br>技术路线调研</h2><p>研究报告 / 2026.11.12<br>范围、证据、步骤与未解问题</p><nav aria-label="报告目录">{nav}</nav><p class="offline">{N_PAPERS} 篇本地论文 · 离线可读<br>本版不作路线推荐</p></aside><main class="layout"><header class="hero"><div class="eyebrow">RESEARCH REPORT / FACTORY-SCALE</div><h1>从机械臂运动，<br>到工厂的状态与演化</h1><p class="subtitle">显式仿真、空间智能、生成式视频、JEPA 等世界模型路线的能力边界与时延；资产路线怎样成为世界模型；机床的主动执行、被动操作和生产资源语义。</p><div class="hero-bottom"><span>调研截止 2026-11-12</span><span>{N_PAPERS} 篇论文全文</span><span>6 条世界模型路线</span><span>不作路线推荐</span><button type="button" id="print">打印 / 导出 PDF</button></div></header><p class="edition">中文研究报告 · 证据与工程推导分别标记 · 所有正文与图表不依赖在线资源</p>{body}<footer>研究范围限定于本次纳入文献；所有实施步骤与实验方案均需现场验证。<a class="back-top" href="#top">回到顶部 ↑</a></footer></main><script>{JS}</script></body></html>'''
document=document.replace('{{N_PAPERS}}',str(N_PAPERS))
assert '{{' not in document and '[[X:' not in document and not re.search(r'\[\[[PS]\d+\]\]',document)
(ROOT/'report.html').write_text(document)
(ROOT/'papers/manifest.json').write_text(json.dumps(records,ensure_ascii=False,indent=2))

with (ROOT/'papers/catalogue.csv').open('w',newline='') as f:
    w=csv.DictWriter(f,fieldnames=['id','title','arxiv_id','doi','publication_title','version','submitted_date','publication_date','pages','bytes','sha256','source_url','pdf_url','local_pdf','status'])
    w.writeheader();w.writerows({k:r.get(k,'') for k in w.fieldnames} for r in records)

bib=[]
for r in records:
    authors=' and '.join(r.get('authors',[]))
    year=(r.get('submitted_date') or r.get('publication_date') or '')[:4]
    entrytype='misc' if r['arxiv_id'] else ('inproceedings' if r.get('booktitle') else ('article' if r.get('doi') else 'techreport'))
    identifier_fields=(f"  eprint = {{{r['arxiv_id']}}},\n  archivePrefix = {{arXiv}}," if r['arxiv_id'] else (f"  doi = {{{r['doi']}}}," if r.get('doi') else ''))
    if entrytype == 'techreport':
        identifier_fields=f"  number = {{{r.get('report_number','')}}},\n  institution = {{{r.get('institution','')}}},"
    venue_fields=(f"\n  journal = {{{r['publication_title']}}}," if r.get('publication_title') else '')
    if r.get('booktitle'):
        venue_fields=f"\n  booktitle = {{{r['booktitle']}}},"
    bib.append(f'''@{entrytype}{{{r['id']}_{r['slug']},
  title = {{{r['title']}}},
  author = {{{authors}}},
  year = {{{year}}},
{identifier_fields}{venue_fields}
  url = {{{r['source_url']}}},
  note = {{Local survey ID {r['id']}; archived {r['version']}; accessed {r['accessed']}}},
  file = {{{Path(r['local_pdf']).name}}}
}}''')
(ROOT/'papers/references.bib').write_text('\n\n'.join(bib)+'\n')
access_dates=sorted({r['accessed'] for r in records})
readme=f'# 论文全文与来源\n\n{N_PAPERS} 篇论文；获取日期 {"、".join(access_dates)}。正文编号与下表一致。PDF 保留原版权／许可证。\n\n|编号|论文|版本|本地全文|\n|---|---|---|---|\n'
readme+='\n'.join(f"|{r['id']}|[{r['title']}]({r['source_url']})|{r['version']}|[{r['pages']} 页]({Path(r['local_pdf']).name})|" for r in records)
readme+='\n\n`manifest.json` 包含作者、摘要、提交历史、下载 URL、大小、页数与 SHA-256；`references.bib` 可导入文献管理器。不同 arXiv 修订版可能与会议终稿存在版式或内容差异。\n'
(ROOT/'papers/README.md').write_text(readme)
print(f'Built report.html: {len(document):,} characters, {len(records)} papers, {len(sections)} sections')
